     6→/// Extract crate name from Cargo.toml
     7→pub fn get_crate_name(crate_dir: &Path) -> Result<String> {
     8→    let cargo_toml = crate_dir.join("Cargo.toml");
     9→    let content = std::fs::read_to_string(&cargo_toml)
    10→        .with_context(|| format!("failed to read {}", cargo_toml.display()))?;
    11→
    12→    // Simple parsing - look for name = "..." in [package] section
    13→    let mut in_package = false;
    14→    for line in content.lines() {
    15→        let line = line.trim();
    16→        if line == "[package]" {
    17→            in_package = true;
    18→            continue;
    19→        }
    20→        if line.starts_with('[') {
    21→            in_package = false;
    22→            continue;
    23→        }
    24→        if in_package
    25→            && line.starts_with("name")
    26→            && let Some(eq_pos) = line.find('=')
    27→        {
    28→            let value = line[eq_pos + 1..].trim();
    29→            let value = value.trim_matches('"').trim_matches('\'');
    30→            return Ok(value.to_string());
    31→        }
    32→    }
    33→    bail!("could not find package name in {}", cargo_toml.display());
    34→}
