   611→fn run_rlibc_x2_tests(workspace_root: &Path, config: &Config) -> Vec<TestResult> {
   612→    let mut results = Vec::new();
   613→
   614→    println!("=== rlibc-x2-tests ===");
   615→
   616→    // First, build the test binaries
   617→    print!("  Building rlibc-x2-tests... ");
   618→
   619→    let mut build_cmd = Command::new("cargo");
   620→    build_cmd.args(["build", "-p", "rlibc-x2-tests"]);
   621→    if !config.debug {
   622→        build_cmd.arg("--release");
   623→    }
   624→    let build_output = build_cmd
   625→        .current_dir(workspace_root)
   626→        .stdout(Stdio::piped())
   627→        .stderr(Stdio::piped())
   628→        .output();
   629→
   630→    match build_output {
   631→        Ok(output) if output.status.success() => {
   632→            println!("ok");
   633→        }
   634→        Ok(output) => {
   635→            println!("FAILED");
   636→            let stderr = String::from_utf8_lossy(&output.stderr);
   637→            eprintln!("{stderr}");
   638→            results.push(TestResult {
   639→                name: "rlibc-x2-tests (build)".to_string(),
   640→                passed: false,
   641→                output: stderr.to_string(),
   642→            });
   643→            return results;
   644→        }
   645→        Err(e) => {
   646→            println!("FAILED");
   647→            eprintln!("  Failed to run cargo build: {e}");
   648→            results.push(TestResult {
   649→                name: "rlibc-x2-tests (build)".to_string(),
   650→                passed: false,
   651→                output: e.to_string(),
   652→            });
   653→            return results;
   654→        }
   655→    }
   656→
   657→    // Find and run test binaries
   658→    let profile = if config.debug { "debug" } else { "release" };
