    26→    let pkg_name = get_crate_name(&crate_dir)?;
    27→
    28→    // Track if we generated a build.rs
    29→    let build_rs_path = crate_dir.join("build.rs");
    30→    let had_build_rs = build_rs_path.exists();
    31→
    32→    // Determine binary path based on spec
    33→    let binary_path = if let Some(path) = &tspec_path {
    34→        let spec = load_spec(path)?;
    35→        get_binary_path(&workspace, &pkg_name, &spec, release)
    36→    } else {
    37→        get_binary_path_simple(&workspace, &pkg_name, release)
    38→    };
    39→
    40→    // Apply spec if present, otherwise plain cargo build
    41→    let status = if let Some(path) = &tspec_path {
    42→        let spec = load_spec(path)?;
    43→        println!("Building {} with spec {}", pkg_name, path.display());
    44→
    45→        // Generate temporary build.rs for linker flags if needed
    46→        let has_linker_args = spec
    47→            .linker
    48→            .iter()
    49→            .any(|p| matches!(p, LinkerParam::Args(_)));
    50→        if has_linker_args && !had_build_rs {
    51→            generate_build_rs(&build_rs_path, &pkg_name, &spec)?;
    52→        }
    53→
    54→        let mut cmd = build_cargo_command(&spec)?;
    55→        cmd.arg("build");
    56→        cmd.arg("-p").arg(&pkg_name);
    57→        cmd.current_dir(&workspace);
    58→
    59→        apply_spec_to_command(&mut cmd, &spec, &workspace, release)?;
    60→        cmd.status().context("failed to run cargo")?
    61→    } else {
    62→        println!("Building {} (no tspec)", pkg_name);
    63→        let mut cmd = Command::new("cargo");
    64→        cmd.arg("build");
    65→        cmd.arg("-p").arg(&pkg_name);
    66→        cmd.current_dir(&workspace);
    67→        if release {
    68→            cmd.arg("--release");
    69→        }
    70→        cmd.status().context("failed to run cargo")?
    71→    };
