    86→/// Generate a temporary build.rs with scoped linker flags from tspec.toml
    87→pub fn generate_build_rs(path: &Path, crate_name: &str, spec: &Spec) -> Result<()> {
    88→    let mut lines = vec![
    89→        "// Generated by xt - do not edit".to_string(),
    90→        "fn main() {".to_string(),
    91→    ];
    92→
    93→    for param in &spec.linker {
    94→        if let LinkerParam::Args(args) = param {
    95→            for arg in args {
    96→                lines.push(format!(
    97→                    "    println!(\"cargo:rustc-link-arg-bin={}={}\");",
    98→                    crate_name, arg
    99→                ));
   100→            }
   101→        }
   102→    }
   103→
   104→    lines.push("}".to_string());
   105→    fs::write(path, lines.join("\n")).context("failed to write build.rs")?;
   106→    Ok(())
   107→}
   108→
   109→/// Check if spec requires nightly toolchain
   110→fn requires_nightly(spec: &Spec) -> bool {
   111→    // BuildStd requires nightly
   112→    let has_build_std = spec
   113→        .rustc
   114→        .iter()
   115→        .any(|p| matches!(p, RustcParam::BuildStd(_)));
   116→
   117→    // Unstable cargo flags require nightly
   118→    let has_unstable = spec
   119→        .cargo
   120→        .iter()
   121→        .any(|p| matches!(p, CargoParam::Unstable(_)));
   122→
   123→    has_build_std || has_unstable
   124→}
   125→
   126→/// Build the base cargo command (with toolchain if needed)
   127→fn build_cargo_command(spec: &Spec) -> Result<Command> {
   128→    let mut cmd = Command::new("cargo");
   129→
   130→    if requires_nightly(spec) {
   131→        cmd.arg("+nightly");
   132→    }
   133→
   134→    Ok(cmd)
   135→}
   136→
   137→/// Apply spec parameters to a cargo command
   138→pub fn apply_spec_to_command(
   139→    cmd: &mut Command,
   140→    spec: &Spec,
   141→    workspace: &Path,
   142→    release: bool,
   143→) -> Result<()> {
   144→    // Handle cargo params
   145→    let mut has_profile = false;
   146→    for param in &spec.cargo {
   147→        match param {
   148→            CargoParam::Profile(p) => {
   149→                has_profile = true;
   150→                match p {
   151→                    Profile::Release => {
   152→                        cmd.arg("--release");
   153→                    }
   154→                    Profile::Debug => {
   155→                        // Debug is default, no flag needed
   156→                    }
   157→                }
   158→            }
   159→            CargoParam::TargetTriple(triple) => {
   160→                cmd.arg("--target").arg(triple);
   161→            }
   162→            CargoParam::TargetJson(path) => {
   163→                cmd.arg("--target").arg(path);
   164→            }
   165→            CargoParam::Unstable(flag) => {
   166→                cmd.arg("-Z").arg(flag);
   167→            }
   168→        }
   169→    }
   170→
   171→    // If no profile in spec but release flag passed, use release
   172→    if !has_profile && release {
   173→        cmd.arg("--release");
   174→    }
   175→
   176→    // Collect rustc flags
   177→    let mut rustc_flags: Vec<String> = Vec::new();
   178→
   179→    // Handle rustc params
   180→    for param in &spec.rustc {
   181→        match param {
   182→            RustcParam::OptLevel(level) => {
   183→                let lvl = match level {
   184→                    crate::types::OptLevel::O0 => "0",
   185→                    crate::types::OptLevel::O1 => "1",
   186→                    crate::types::OptLevel::O2 => "2",
   187→                    crate::types::OptLevel::O3 => "3",
   188→                    crate::types::OptLevel::Os => "s",
   189→                    crate::types::OptLevel::Oz => "z",
   190→                };
   191→                rustc_flags.push(format!("-C opt-level={}", lvl));
   192→            }
   193→            RustcParam::Panic(strategy) => {
   194→                let s = match strategy {
   195→                    crate::types::PanicStrategy::Abort => "abort",
   196→                    crate::types::PanicStrategy::Unwind => "unwind",
   197→                    crate::types::PanicStrategy::ImmediateAbort => "immediate-abort",
   198→                };
   199→                rustc_flags.push(format!("-C panic={}", s));
   200→            }
   201→            RustcParam::Lto(enabled) => {
   202→                if *enabled {
   203→                    rustc_flags.push("-C lto=true".to_string());
   204→                }
   205→            }
   206→            RustcParam::CodegenUnits(n) => {
   207→                rustc_flags.push(format!("-C codegen-units={}", n));
   208→            }
   209→            RustcParam::BuildStd(crates) => {
   210→                // -Z build-std is a cargo flag, not rustc
   211→                let crates_str = crates.join(",");
   212→                cmd.arg("-Z").arg(format!("build-std={}", crates_str));
   213→            }
   214→            RustcParam::Flag(flag) => {
   215→                rustc_flags.push(flag.clone());
   216→            }
   217→        }
   218→    }
   219→
   220→    // Handle version script (generates file and adds linker arg)
   221→    for param in &spec.linker {
   222→        if let LinkerParam::VersionScript(vs) = param {
   223→            let target_dir = workspace.join("target");
   224→            let _ = fs::create_dir_all(&target_dir);
   225→            let version_script_path = target_dir.join("xt-version.script");
   226→
   227→            // Generate version script: { global: sym1; sym2; local: *; };
   228→            let globals = vs.global.join("; ");
   229→            let content = format!("{{ global: {}; local: {}; }};", globals, vs.local);
   230→
   231→            let mut f = fs::File::create(&version_script_path)
   232→                .context("failed to create version script")?;
   233→            writeln!(f, "{}", content)?;
   234→
   235→            rustc_flags.push(format!(
   236→                "-C link-arg=-Wl,--version-script={}",
   237→                version_script_path.display()
   238→            ));
   239→        }
   240→    }
   241→
   242→    // Apply rustc flags (linker args from Args handled by generated build.rs)
   243→    if !rustc_flags.is_empty() {
   244→        cmd.env("RUSTFLAGS", rustc_flags.join(" "));
   245→    }
   246→
   247→    Ok(())
   248→}
